import { createClient, type SupabaseClient } from '@supabase/supabase-js';
import type { Database } from './types';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY;

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

const isDev = import.meta.env.DEV;
const FORCE_PROXY = import.meta.env.VITE_FORCE_PROXY === 'true' || import.meta.env.VITE_FORCE_PROXY === '1';

// URL base para functions - em dev usa proxy local do Vite
const FUNCTIONS_BASE_URL = isDev || FORCE_PROXY ? "/functions/v1" : `${SUPABASE_URL}/functions/v1`;

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  },
  global: {
    headers: {
      apikey: SUPABASE_PUBLISHABLE_KEY,
    },
  },
});

// Patch profundo: intercepta o fetch interno do Supabase Functions
// Isso é necessário porque o SDK mantém referências internas ao método original
function setupProxy() {
  // Só aplica em dev ou quando FORCE_PROXY está ativo
  if (!isDev && !FORCE_PROXY) return;

  try {
    // Patch the functions object's invoke method
    const functions = (supabase as any).functions;
    if (functions && functions.invoke) {
      const originalInvoke = functions.invoke.bind(functions);

      (functions as any).invoke = async function<T = any>(
        functionName: string,
        options?: { body?: any; headers?: Record<string, string>; method?: "GET" | "POST" | "PUT" | "DELETE" }
      ): Promise<{ data: T | null; error: any }> {
        const url = `/functions/v1/${functionName}`;
        const method = options?.method || "POST";

        try {
          // Pega o token de sessão do localStorage
          const sessionData = typeof window !== "undefined"
            ? localStorage.getItem("sb-fygxlswpkjtjpcefjfty-auth-token")
            : null;

          const headers: Record<string, string> = {
            "Content-Type": "application/json",
            "apikey": SUPABASE_PUBLISHABLE_KEY,
            ...options?.headers,
          };

          if (sessionData) {
            try {
              const parsed = JSON.parse(sessionData);
              if (parsed?.access_token) {
                headers.Authorization = `Bearer ${parsed.access_token}`;
              }
            } catch {}
          }

          const response = await fetch(url, {
            method,
            headers,
            body: method === "GET" ? undefined : JSON.stringify(options?.body),
          });

          if (!response.ok) {
            const text = await response.text();
            return {
              data: null,
              error: { status: response.status, message: text, name: "FunctionsFetchError" },
            };
          }

          const data = await response.json();
          return { data, error: null };
        } catch (err: any) {
          return { data: null, error: err };
        }
      };
    }

    // Also patch the internal fetch if it exists
    if (functions && (functions as any).fetch) {
      const originalFetch = (functions as any).fetch.bind(functions);

      (functions as any).fetch = async function(url: string, options?: any) {
        // Check if this is a functions URL that needs proxying
        if (typeof url === 'string' && url.includes('/functions/v1/')) {
          const functionName = url.split('/functions/v1/')[1];
          const proxiedUrl = `/functions/v1/${functionName}`;

          // Get auth token
          const sessionData = typeof window !== "undefined"
            ? localStorage.getItem("sb-fygxlswpkjtjpcefjfty-auth-token")
            : null;

          const headers: Record<string, string> = {
            "Content-Type": "application/json",
            "apikey": SUPABASE_PUBLISHABLE_KEY,
            ...(options?.headers || {}),
          };

          if (sessionData) {
            try {
              const parsed = JSON.parse(sessionData);
              if (parsed?.access_token) {
                headers.Authorization = `Bearer ${parsed.access_token}`;
              }
            } catch {}
          }

          return fetch(proxiedUrl, {
            ...options,
            headers,
          });
        }

        return originalFetch(url, options);
      };
    }

    console.log('[CORS Proxy] Supabase functions proxy configured successfully');
  } catch (err) {
    console.error('[CORS Proxy] Failed to setup proxy:', err);
  }
}

// Setup proxy immediately
setupProxy();

// Also setup a global fetch interceptor as fallback
if ((isDev || FORCE_PROXY) && typeof window !== "undefined") {
  const originalFetch = window.fetch.bind(window);

  window.fetch = async function(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
    const url = typeof input === 'string' ? input : input instanceof URL ? input.href : (input as Request).url;

    // Proxy Supabase functions calls
    if (typeof url === 'string' && url.includes('.supabase.co/functions/v1/')) {
      const functionName = url.split('/functions/v1/')[1];
      const proxiedUrl = `/functions/v1/${functionName}`;

      // Get auth token
      const sessionData = localStorage.getItem("sb-fygxlswpkjtjpcefjfty-auth-token");
      const headers: Record<string, string> = {
        "Content-Type": "application/json",
        "apikey": SUPABASE_PUBLISHABLE_KEY,
        ...(init?.headers as Record<string, string> || {}),
      };

      if (sessionData) {
        try {
          const parsed = JSON.parse(sessionData);
          if (parsed?.access_token) {
            headers.Authorization = `Bearer ${parsed.access_token}`;
          }
        } catch {}
      }

      return originalFetch(proxiedUrl, {
        ...init,
        headers,
      });
    }

    return originalFetch(input, init);
  };

  console.log('[CORS Proxy] Global fetch interceptor configured');
}
